import{_ as s,o,c as r,a2 as t}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Ajouter des mods et du contenu","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mods.md","filePath":"guide/mods.md"}'),n={name:"guide/mods.md"};function a(i,e,l,d,u,c){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="ajouter-des-mods-et-du-contenu" tabindex="-1">Ajouter des mods et du contenu <a class="header-anchor" href="#ajouter-des-mods-et-du-contenu" aria-label="Permalink to &quot;Ajouter des mods et du contenu&quot;">​</a></h1><p>Le contenu se gère depuis la page de l&#39;instance : cliquez sur son nom dans la colonne de gauche, puis sur l&#39;onglet <strong>Contenu</strong>.</p><ol><li>Choisissez l&#39;onglet : <strong>Mods</strong>, <strong>Resource packs</strong>, <strong>Datapacks</strong> ou <strong>Shaders</strong>. Un onglet grisé n&#39;est pas disponible pour cette instance (par exemple, les mods en Vanilla).</li><li>Par défaut, Kodus affiche les contenus les plus téléchargés pour votre version et votre loader. Utilisez la barre de recherche pour trouver un contenu précis.</li><li>Cliquez sur <strong>Installer</strong>. Kodus sélectionne la version compatible et installe les dépendances nécessaires.</li><li>Lancez le jeu : le mod est actif.</li></ol><h2 id="la-colonne-«-installes-»" tabindex="-1">La colonne « Installés » <a class="header-anchor" href="#la-colonne-«-installes-»" aria-label="Permalink to &quot;La colonne « Installés »&quot;">​</a></h2><ul><li>L&#39;interrupteur active ou désactive un mod sans le supprimer (utile pour identifier un mod à l&#39;origine d&#39;un plantage).</li><li>La croix supprime le mod.</li><li>Le bouton <strong>Tout mettre à jour</strong> apparaît lorsque des mises à jour compatibles avec votre version de Minecraft sont disponibles.</li></ul><h2 id="mods-recommandes" tabindex="-1">Mods recommandés <a class="header-anchor" href="#mods-recommandes" aria-label="Permalink to &quot;Mods recommandés&quot;">​</a></h2><p>Parmi les plus utilisés : <strong>Sodium</strong> (performances), <strong>Iris</strong> (shaders), <strong>Mod Menu</strong> (liste des mods en jeu), <strong>AppleSkin</strong> (affichage de la faim et de la saturation), <strong>Xaero&#39;s Minimap</strong> (minicarte).</p><h2 id="cas-particuliers" tabindex="-1">Cas particuliers <a class="header-anchor" href="#cas-particuliers" aria-label="Permalink to &quot;Cas particuliers&quot;">​</a></h2><ul><li><strong>Shaders</strong> : le mod Iris est requis. Kodus propose un bouton <strong>Installer Iris</strong> s&#39;il est absent.</li><li><strong>Datapacks</strong> : ils s&#39;installent dans un monde. Créez d&#39;abord un monde en jeu, puis sélectionnez-le dans l&#39;onglet Datapacks.</li><li><strong>Mod obtenu ailleurs</strong> (fichier <code>.jar</code>) : cliquez sur <strong>Ouvrir le dossier</strong> et déposez-y le fichier. Vérifiez qu&#39;il correspond à votre version et à votre loader.</li></ul>',9)])])}const g=s(n,[["render",a]]);export{m as __pageData,g as default};
